/// <summary>
/// designed by AVANADE
/// </summary>
class AVACustQuotationJourPostGAEB extends RunBaseBatch
{
    SalesQuotationTable             salesQuotationTable;
    SalesQuotationLine              salesQuotationLine;
    SalesQuotationParmTable         salesQuotationParmTable;
    SalesQuotationParmLine          salesQuotationParmLine;
    SalesQuotationParmUpdate        salesQuotationParmUpdate;
    Counter                         numberOfRecords;
    Counter                         recordsUpdated;
    DocumentStatus                  documentStatus;
    str                             parmSalesProj;
    container                       callerRecordsPackedMap;
    ParmId                          parmid;
    CustQuotationJour               custQuotationJour;

    #define.CurrentVersion(4)
    #localmacro.CurrentList
        DocumentStatus,
        parmSalesProj,
        SalesQuotationTable
    #endmacro
}

Method.Source:
public void run()
{
    this.parmInBatch(false);

    conIns(callerRecordsPackedMap,1,salesQuotationTable);

    SalesQuotationEditLinesForm salesQuotationEditLinesForm = SalesQuotationEditLinesForm::construct(documentStatus, parmSalesProj);

    //this.initializeAndRun(salesQuotationEditLinesForm, documentStatus, parmSalesProj, salesQuotationTable, callerRecordsPackedMap);
    this.initializeAndRun(salesQuotationEditLinesForm, salesQuotationTable, callerRecordsPackedMap);

    this.parmCustQuotationJour(custQuotationJour::findRecId(salesQuotationEditLinesForm.parmCustQuotationJourRecId()));


}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "EditLinesForm">SalesQuotationEditLinesForm</param>
/// <param name = "_record">Common</param>
/// <param name = "_callerRecordsPackedMap">container</param>
//private void initializeAndRun(SalesQuotationEditLinesForm EditLinesForm, DocumentStatus _documentStatus, str _parmSalesProj, Common _record, container _callerRecordsPackedMap)
private void initializeAndRun(SalesQuotationEditLinesForm EditLinesForm, Common _record, container _callerRecordsPackedMap)
{
    QuotationIdBase origQuotationId;
    SRSPrintDestinationSettings    printJobSettings;
    SalesQuotationEditLinesForm_Sales_Send  editLinesFormSalesSend;

    if (EditLinesForm.handle() == className2Id(classStr(SalesQuotationEditLinesForm_Sales_Send)))
    {
        editLinesFormSalesSend = EditLinesForm;
    }
    else
    {
        return;
    }


    if (_record)
    {
        if (_record.TableId == tableNum(SalesQuotationTable))
        {
            EditLinesForm.salesQuotationTable(_record);
            CallerRecordsPackedMap = _callerRecordsPackedMap;
            origQuotationId = salesQuotationTable.QuotationId;
        }
    }

    parmid = NumberSeq::newGetNum(CompanyInfo::numRefParmId()).num();
    EditLinesForm.parmId(parmId);
    EditLinesForm.parmTransDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    EditLinesForm.parmSendMode(KCS_SendMode::GAEB);

    printJobSettings = new SRSPrintDestinationSettings(editLinesFormSalesSend.printerSettingsFormletter());
    printJobSettings.printMediumType(SRSPrintMediumType::File);
    printJobSettings.fileFormat(SRSReportFileFormat::PDF);
    printJobSettings.fileName(strFmt('%1%2', origQuotationId, '.pdf'));
    EditLinesFormSalesSend.updatePrinterSettingsFormLetter(printJobSettings.pack());
    EditLinesFormSalesSend.printFormLetter(true);        

    EditLinesForm.prePromptInit();
    EditLinesForm.runOperation();
    //this.parmCustQuotationJour(custQuotationJour::findRecId(editLinesFormSalesSend.parmCustQuotationJourRecId()));

}

public CustQuotationJour  parmCustQuotationJour(CustQuotationJour _CustQuotationJour = CustQuotationJour)
{
    CustQuotationJour = _CustQuotationJour;
    return CustQuotationJour;
}

public DocumentStatus  parmDocumentStatus(DocumentStatus _docStatus = DocumentStatus)
{
    documentStatus = _docStatus;
    return documentStatus;
}

public str parmSalesProj(str _parmSalesProj = parmSalesProj)
{
    parmSalesProj = _parmSalesProj;
    return parmSalesProj;
}

public SalesQuotationTable parmSalesQuotationTable(SalesQuotationTable _salesQuotationTable = SalesQuotationTable)
{
    salesQuotationTable  = _salesQuotationTable;
    return salesQuotationTable;
}

public boolean unpack(container packedClass)
{
    Version version = runbase::getVersion(packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

static AVACustQuotationJourPostGAEB construct(Args _args)
{
    AVACustQuotationJourPostGAEB custQuotationJourPost = new AVACustQuotationJourPostGAEB();

    custQuotationJourPost.parmDocumentStatus(_args.parmEnum());
    custQuotationJourPost.parmSalesProj(_args.parm());
    custQuotationJourPost.parmSalesQuotationTable(_args.record());

    return custQuotationJourPost;
}

